abla}u\vert^2 \dvv. \end{equation} Combining (ef{2.40}), (ef{2.39}) and (ef{2.38}) with item (3) of Lemma ef{L.2.2}, we find  egin{equation} (1-k^+)\int_{S\M} \vert \overset{\hh}{
abla} u \vert ^2 \dvv+(n-2) \int_{S\M} \vert Hu\vert ^2 \dvv\leq C \Vert \I f \Vert^2_{H^1(\p_+S\M)}. \end{equation} For $k^+<1$ and $n\geq 2$, we deduce the estimate  egin{equation} \int_{S\M} \vert \overset{\hh}{
abla} u \vert ^2 \dvv \leq C \Vert \I f \Vert^2_{H^1(\p_+S\M)}. \end{equation} In view of the definition of $H$, in (ef{2.30}), there exists a constant $C$ such that $$ \vert Hu \vert^2 \leq C \vert \overset{\hh}{
abla} u \vert ^2 . $$ Using the item (2) of Lemma ef{L.2.2} and (ef{2.30}), we conclude that $$ \Vert f \Vert ^2_{L^2(S\M)}=\int_{S\M} \vert Hu \vert^2 \dvv\leq C \int_{S\M} \vert \overset{\hh}{
abla} u \vert ^2 \dvv \leq C\Vert\I f \Vert^2_{H^1(\p_+S\M)}, $$ and the Theorem ef{theorem} is done. \ Now, we come back to prove (ef{2.38})-(ef{2.39}) and (ef{2.40}). First, we start with (ef{2.40}). By (ef{2.8}) we find  egin{equation} \vert \langle R(\xi,\overset{\vv}{
abla} u)\xi, \overset{\vv}{
abla} uangle \vert \leq K^+(x,\xi) \vert \overset{\vv}{
abla} u(x,\xi) \vert^2,\quad  orall (x,\xi)\in S\M. \end{equation} Furthermore, the lemma ef{L.2.3} combined with (ef{2.43}) gives the following estimate  egin{align} \int_{S \M} \vert \langle R(\xi,\overset{\vv}{
abla} u)\xi, \overset{\vv}{
abla} uangle \vert \dvv & \leq k^+ \int_{S \M} \vert H\overset{\vv}{
abla} u \vert^2 \dvv & \cr & \leq k^+ \int_{S \M} \vert \overset{\hh}{
abla} u \vert^2 \dvv, \end{align} This completes the proof of (ef{2.40}).\ We prove now (ef{2.38}). Since we have $Hu=-f$ and $\overset{\vv}{
abla}f=0$, then the Pestov's identity (ef{2.31}) gives  egin{equation} \vert \overset{\hh}{
abla} u \vert^2+ \overset{\hh}{\dive}(V) + \overset{\vv}{\dive}(W)- \langle R(\xi,\overset{\vv}{
abla} u)\xi, \overset{\vv}{
abla} uangle=0. \end{equation} Avoiding eventual singularities of $u$ on $T \p\M$, we will consider the variety $\M_{ho}$ defined by $$\M_{ho}=\{x \in \M,\quad d_\g(x,\p \M) \geq ho \},$$ where $ho >0$. In some neighbourhood of $\p \M,$ the function $x \mapsto d_\g(x,\p \M)$ is smooth and $\p \M_{ho}$ is strictly convex for sufficiently small $ho >0.$ The function $u$ is smooth on $S\M_{ho}$ since $S\M_{ho}\subset S\M \setminus S(\p \M)$. Integrating (ef{2.45}) over $S\M_{ho}$ and using the formula divergence (ef{2.27}) and (ef{2.28}), we find  egin{align*} \int_{S\M_{ho}}\left[ \vert \overset{\hh}{
abla} u \vert^2- \langle R(\xi,\overset{\vv}{
abla} u)\xi, \overset{\vv}{
abla} uangleight]\, \dvv= & -\int_{S\M_{ho}} \left[ \overset{\hh}{\dive}(V) + \overset{\vv}{\dive}(W)ight]\, \dvv \cr =& -\int_{\p S\M_{ho}} \langle V, 
u angle \quad d\sigma^{2n-2} -(n-2)\int_{S\M_{ho}} \langle W, \xi angle \dvv, \end{align*} where $
u=
u_{ho}(x)$ is the unit vector of the outer normal to the boundary of $\M_{ho}$. In view of (ef{2.33}), we have $$\langle W, \xi angle=\langle\xi,\overset{\hh}{
abla} uangle ^2 = \vert Hu\vert ^2.$$ Hence, we obtain the equality  egin{equation} \int_{S\M_{ho}}\left[ \vert \overset{\hh}{
abla} u \vert^2- \langle R(\xi,\overset{\vv}{
abla} u)\xi, \overset{\vv}{
abla} uangle+(n-2) \vert Hu\vert^2 ight] \dvv= -\int_{\p S\M_{ho}} \langle V, 
u angle \,d\sigma^{2n-2}. \end{equation} Now, we wish pass to the limit as $ho ightarrow 0.$ We will apply the Lebesgue dominated convergence theorem. Denote by $\mathbb{\chi}_ho$ the characteristic function of the set $S\M_{ho}$ and by $p$ the projection $p : \p S\M \longrightarrow \p S\M_ho$, $p(x,\xi)=(x',\xi'),$ where $x'$ is such that the geodesic $\gamma_{xx'}$ has length $ho$ and intersects $\p \M$ orthogonally at $x$ and $x'$, and $\xi'$ is obtained by the parallel translation of the vector $\xi$ along $\gamma_{xx'}$. So the equality (ef{2.46}) becomes  egin{equation} \int_{S\M}\left[ \vert \overset{\hh}{
abla} u \vert^2- \langle R(\xi,\overset{\vv}{
abla} u)\xi, \overset{\vv}{
abla} uangle+(n-2) \vert Hu\vert ^2 ight] \mathbb{\chi}_ho \dvv= -\int_{\p S\M} \langle V, 
u angle p_* ( d\sigma^{2n-2}). \end{equation} Note that all the integrands of (ef{2.47}) are smooth on $S\M \setminus \p S \M$ and so, they converge towards their values almost everywhere, when $ho ightarrow 0$. Since the functions $\vert \overset{\hh}{
abla} u \vert^2$ and $\vert Hu\vert ^2$ are positive and the second function satifies (ef{2.43}), then the left side of (ef{2.47}) converges as $ho ightarrow 0$. To apply the Lebesgue dominated convergence theorem in (ef{2.47}), it remains to prove that $\vert \langle V, 
u angle p_* \vert$ is bounded by a summable function on $\p S \M$ which does not depend on $ho$.\ For $(x,\xi)\in \p S\M$, we put $$ \overset{\hh}{
abla}_{	extrm{tan}} u =\overset{\hh}{
abla} u -\langle\overset{\hh}{
abla} u ,
uangle
u,\quad \overset{\vv}{
abla}_{	extrm{tan}} u =\overset{\vv}{
abla} u -\langle\overset{\vv}{
abla} u,\xiangle\xi. $$ We see that $$ \langle\overset{\hh}{
abla}_{	extrm{tan}} u ,
uangle=\langle\overset{\vv}{
abla}_{	extrm{tan}} u,\xiangle=0. $$ Then $\overset{\hh}{
abla}_{	extrm{tan}}$ and $\overset{\vv}{
abla}_{	extrm{tan}}$ are in fact differential operators on $\p S\M$ and $\overset{\hh}{
abla}_{	extrm{tan}}u$, $\overset{\vv}{
abla}_{	extrm{tan}}u$ are completely determined by the restriction $u_{|\p S\M}$ of $u$ on $\p S\M$.\ For $(x,\xi)\in\p S\M$, by a simple computation we obtain  egin{equation} \langle V, 
u angle=\langle \overset{\hh}{
abla}_{	extrm{tan}} u , \overset{\vv}{
abla}_{	extrm{tan}} u angle\langle\xi,
uangle-\langle \overset{\hh}{
abla}_{	extrm{tan}} u , \xiangle\langle \overset{\vv}{
abla}_{	extrm{tan}} u ,
uangle. \end{equation} From (ef{2.34}), we can see that the derivatives $\overset{\hh}{
abla}_{	extrm{tan}}u$ and $\overset{\vv}{
abla}_{	extrm{tan}} u$ are locally bounded on $\p S\M$. It is important that the right-hand side of (ef{2.48}) does not contain $\langle\overset{\hh}{
abla} u,
uangle$ and $\langle\overset{\vv}{
abla}u,\xi angle.$\ Taking $ho ightarrow 0$ in the equality (ef{2.46}), we have $$ \int_{S\M} \left[ \vert \overset{\hh}{
abla} u \vert ^2-\langle R(\xi,\overset{\vv}{
abla} u)\xi, \overset{\vv}{
abla} uangle+ (n-2) \vert Hu\vert ^2 ight]\dvv= -\int_{\p S\M} \langle V, 
u angle \dss. $$ Finally, It remains to prove the estimate (ef{2.39}). In view of the boundary condition $u=\I f$ on $\p_+S\M$ and $u=0$ on $\p_-S\M$ we obtain  egin{align*} \int_{\p S\M} \langle V, 
u angle \dss &=\int_{\p_+ S\M} \para{\langle \overset{\hh}{
abla}_{	extrm{tan}} (\I f) , \overset{\vv}{
abla}_{	extrm{tan}} (\I f) angle\langle\xi,
uangle-\langle \overset{\hh}{
abla}_{	extrm{tan}} (\I f) , \xiangle\langle \overset{\vv}{
abla}_{	extrm{tan}} (\I f) ,
uangle} \dss\cr & :=\int_{\p_+ S\M} \mathcal{Q}(\I f) \dss . \end{align*} where $\mathcal{Q}u$ is a quadratic form in variables $\overset{\hh}{
abla}_{	extrm{tan}}u$ and $\overset{\vv}{
