Let $r(x,t;h)$ solves the following homogenous boundary value problem  egin{equation} \left\{  egin{array}{llll} \para{\partial^2_t-\Op}r(x,t)=V_h (x,t) & 	extrm{in }\,\, Q,\cr r(x,0)=\p_tr(x,0)=0,& 	extrm{in }\,\,\M,\cr r(x,t)=0 & 	extrm{on} \,\, \Sigma. \end{array} ight. \end{equation} where the source term $V_h$ is given by  egin{equation} V_h(x,t)=-\para{\partial_t^2-\Op}\para{(	heta\psi_a)(x,t)e^{i\varphi/h}}. \end{equation} To prove our Lemma it would be enough to show that $r$ satisfies the estimates (ef{3.25}).\ By a simple computation, we have  egin{align} -V_h (x,t)&=e^{i\varphi(x,t)/h}\para{\p_t^2-\Op}\para{(	heta\psi_a)( x,t)}\cr &\quad - rac{2i}{h} e^{i\varphi(x,t)/h}\psi_a(x,t)\para{\p_t	heta+\seq{d\varrho,d	heta}+ rac{	heta}{2}\Delta\varrho}( x,t)\cr &\quad - rac{2i}{h} e^{i\varphi(x,t)/h}	heta(x,t)\para{\p_t\psi_a+\seq{d\varrho,d\psi_a}+ rac{a}{2} \psi_a}(x,t)\cr &\quad- rac{1}{h^2} 	heta\psi_a(x,t) e^{i\varphi(x,t)/h}\para{1-\abs{d\varrho}^2}. \end{align} Taking into account (ef{3.7})-(ef{3.11}) and (ef{3.12}), the right-hand side of (ef{3.28}) becomes  egin{align} V_h (x,t)&=-e^{i\varphi(x,t)/h}(\p_t^2-\Op)\para{(	heta\psi_a)(x,t)} \cr &\equiv-e^{i\varphi(x,t)/h}V_0(x,t). \end{align} Since $	heta\in\mathcal{V}(Q)$ and $\psi_a\in\mathcal{W}(Q)$ we deduce that $V_0\in H^1_0(0,T;L^2(\M))$. Furthermore, there is a constant $C>0$, such that  egin{equation} 
orm{V_0}_{L^2(Q)}+
orm{\p_tV_0}_{L^2(Q)}\leq C
orm{	heta}_{\mathcal{V}(Q)}. \end{equation} By Lemma ef{L.1.1}, we find  egin{equation} r_h\in \mathcal{C}^2(0,T;L^2(\M))\cap\mathcal{C}^1(0,T;H^1_0(\M))\cap\mathcal{C}(0,T;H^2(\M)). \end{equation} Since the coefficients $a$ and $q$ do not depend on $t$, the function $$ r^*_h(x,t)=\int_0^tr_h(x,s)ds, $$ solves the mixed hyperbolic problem (ef{3.26}) with the right side $$ V^*_h(x,t)=\int_0^tV_h (x,s)ds=-ih\int_0^tV_0(x,s)\p_s\para{e^{i\varphi(x,s)/h}}ds. $$ Integrating by part with respect to $s$, we conclude that $$ 
orm{V^*_h}_{L^2(Q)}\leq Ch
orm{	heta}_{\mathcal{V}(Q)}. $$ and by (ef{1.5}), we get  egin{eqnarray} 
orm{r_h(\cdot,t)}_{L^2(\M)}=
orm{\p_tr^*_h(\cdot,t)}_{L^2(\M)}\leq Ch
orm{	heta}_{\mathcal{V}(Q)}. \end{eqnarray} Since $
orm{V_h }_{L^2(Q)}+h
orm{\p_tV_h }_{L^2(Q)}\leq C
orm{	heta}_{\mathcal{V}(Q)}$, by using again the energy estimates for the problem (ef{3.26}), obtain  egin{eqnarray} 
orm{\p_tr_h(\cdot,t)}_{L^2(\M)}+
orm{
abla r_h (\cdot,t)}_{L^2(\M)}\leq C
orm{	heta}_{\mathcal{V}(Q)}. \end{eqnarray} and by (ef{1.6}), we have  egin{eqnarray} 
orm{\p_t^2 r_h(\cdot,t)}_{L^2(\M)}+
orm{
abla\p_t r_h(\cdot,t)}_{L^2(\M)}+
orm{\Delta r_h(\cdot,t)}_{L^2(\M)}\leq Ch^{-1}
orm{	heta}_{\mathcal{V}(Q)}. \end{eqnarray} Collecting (ef{3.32})-(ef{3.33}) and (ef{3.34}) we get (ef{3.25}). The proof is complete.

First, if $	heta_2$ satisfies (ef{3.11}), $\psi_{a_2}$ satisfies (ef{3.12}), and $h<h_0$, Lemma ef{L.3.2} guarantees the existence of a geometrical optics solution $u_2$  egin{equation} u_2(x,t)=(	heta_2\psi_{a_2})(x,t)e^{i\varphi(x,t)/h}+r_{2,h}(x,t), \end{equation} to the wave equation corresponding to the coefficients $a_2$ and $q_2$, $$ \para{\p^2_t-\Ops}u(x,t)=0\quad 	extrm{in}\,Q, \quad u(\cdot,0)=\p_tu(\cdot,0)=0 \quad 	extrm{in}\,\, \M, $$ where $r_{2,h}$ satisfies  egin{gather} h^{-1}
orm{r_{2,h}(\cdot,t)}_{L^2(\M)}+
orm{\p_t r_{2,h}(\cdot,t)}_{L^2(\M)}+
orm{
abla r_{2,h}(\cdot,t)}_{L^2(\M)}\leq C
orm{	heta_2}_{\mathcal{V}(Q)}, \ 
onumber r_{2,h}(x,t)=0,\quad orall (x,t)\in\,\Sigma. \end{gather} Moreover $$ u_2\in \mathcal{C}^2(0,T;L^2(\M))\cap \mathcal{C}^1(0,T;H^1(\M)) \cap \mathcal{C}(0,T;H^2(\M)). $$ Let us denote by $f_h$ the function $$ f_h(x,t)=(	heta_2\psi_{a_2})(x,t)e^{i\varphi(x,t)/h},\quad (x,t)\in\Sigma, $$ and we consider $v$ the solution of the following non-homogenous boundary value problem  egin{equation} \left\{ egin{array}{lll} \para{\p_t^2-\Opf} v=0, & 	extrm{in}\,\, Q,\cr v(x,0)=\p_tv(x,0)=0, & 	extrm{in}\,\, \M,\cr v(x,t)=u_2(x,t):=f_{h}(x,t), & 	extrm{on}\,\, \Sigma. \end{array} ight. \end{equation} We let $ w=v-u_2$. Therefore, $w$ solves the following homogenous boundary value problem $$ \left\{ egin{array}{lll} \para{\p_t^2-\Opf}w(x,t)=a(x)\p_tu_2(x,t)+q(x)u_2(x,t) & 	extrm{in}\,\, Q,\cr w(x,0)=\p_tw(x,0)=0, & 	extrm{in}\,\, \M,\cr w(x,t)=0, & 	extrm{on}\,\, \Sigma. \end{array} ight. $$ Using the fact that $a(x)\p_tu_2+q(x)u_2 \in W^{1,1}(0,T;L^2(\M))$ with $u_2(\cdot,0)=\p_t u_2(\cdot,0)\equiv 0$, by Lemma ef{L.1.1}, we deduce that $$ w\in \mathcal{C}^1(0,T;L^2(\M))\cap \mathcal{C}(0,T;H^2(\M)\cap H^1_0(\M)). $$ Therefore, we have constructed a special solution $$ \mathcal{C}^2(0,T;L^2(\M))\cap \mathcal{C}^1(0,T;H^1(\M)) \cap \mathcal{C}(0,T;H^2(\M)), $$ to the backward wave equation  egin{align*} \para{\partial_t^2-\Delta-a_1(x)\p_t+q_1(x)}u_1(x,t)&=0, \quad (x,t) \in Q, \ u_1(x,T)=u_1(x,T)&=0, \quad x \in \M, \end{align*} having the special form  egin{equation} u_1(x,t)=(	heta_1\psi_{-a_1})( t,x)e^{i\varphi(x,t)/h}+r_{1,h}(x,t), \end{equation} which corresponds to the coefficients $-a_1$ and $q_1$, where $r_{1,h}$ satisfies for $h<h_0$  egin{equation} h^{-1}
orm{r_{1,h}(\cdot,t)}_{L^2(\M)}+
orm{\p_t r_{1,h}(\cdot,t)}_{L^2(\M)}+
orm{
abla r_{1,h}(\cdot,t)}_{L^2(\M)}\leq C
orm{	heta_1}_{\mathcal{V}(Q)}. \end{equation} Integrating by parts and using Green's formula (ef{3.4}), we find  egin{multline} \int_0^T\!\!\!\int_\M\para{\p_t^2-\Opf}w\overline{u}_1\dv \, \dd t = \int_0^T\!\!\!\int_\M a(x)\p_tu_2\overline{u}_1\dv \, \dd t\cr +\int_0^T\!\!\!\int_\M q(x)u_2\overline{u}_1\dv \, \dd t =-\int_0^T\!\!\!\int_{\p \M} \p_
u w\overline{u}_1\ds \, \dd t. \end{multline} Taking (ef{4.8}), (ef{4.6}) into account, we deduce  egin{multline} -\int_0^T\!\!\!\int_\M a(x)\p_tu_2\overline{u}_1(x,t)\dv\,\dd t =\int_0^T\!\!\!\int_{\p \M}\para{\Lambda_{a_1,q_1}-\Lambda_{q_2,q_2}} f_{h}(x,t)\overline{g}_h(x,t) \ds \, \dd t\cr +\int_0^T\!\!\!\int_\M q(x)u_2\overline{u}_1\dv \, \dd t \end{multline} where $g_h$ is given by $$ g_h(x,t)=(	heta_1\psi_{-a_1})(x,t)e^{i\varphi(x,t)/h},\quad (x,t)\in \Sigma. $$ It follows from (ef{4.9}), (ef{4.6}) and (ef{4.3}) that  egin{multline} ih^{-1}\int_0^T\!\!\!\int_\M a(x) (	heta_2 \overline{	heta}_1)(x,t)(\psi_{a_2}\psi_{-a_1})( x,t)\dv\,\dd t =\cr \int_0^T\!\!\!\int_{\p \M} \overline{g}_h\para{\Lambda_{a_1,q_1}-\Lambda_{a_2,q_2}}f_{h} \ds \, \dd t -ih^{-1}\int_0^T\!\!\!\int_\M a(x) (	heta_2\psi_{a_2})(x,t)\overline{r}_{1,h}e^{i\varphi/h}\dv\dd t\cr +\int_0^T\!\!\!\int_\M a(x)\p_t(	heta_2\psi_{a_2})(x,t)\overline{	heta}_1\psi_{a_1}(x,t)\dv\dd t +\int_0^T\!\!\!\int_\M a(x)\p_t(	heta_2\psi_{a_2})(x,t)\overline{r}_{1,h}(t,x)e^{i\varphi/h}\dv\dd t\cr +\int_0^T\!\!\!\int_\M a(x)\p_t r_{2,h}(\overline{	heta}_1\psi_{a_1})(x,t) e^{-i\varphi/h}\dv\dd t +\int_0^T\!\!\!\int_\M a(x)\p_tr_{2,h}(x,t)\overline{r}_{1,h}(x,t)\dv\dd t\cr +\int_0^T\!\!\!\int_\M q(x)u_2(x,t)\overline{u}_1(x,t)\dv dt \cr = \int_0^T\!\!\!\int_{\p \M} \overline{g}_h \para{\Lambda_{a_1,q_1}-\Lambda_{a_2,q_2}}f_{h} \ds \, \dd t+\mathscr{R}_h. \end{multline} In view of (ef{4.7}) and (ef{4.4}), we have  egin{equation} \abs{\mathscr{R}_h}\leq C
orm{	heta_1}_{\mathcal{V}(Q)}
orm{	heta_2}_{\mathcal{V}(Q)}. \end{equation} On the other hand, by the trace theorem, we find  egin{eqnarray}  igg|\int_0^T\!\!\!\int_{\p \M}\para{\Lambda_{a_1,q_1}-\Lambda_{a_2,q_2}}(f_{h}) \overline{g}_h \ds \, \dd t  igg| &\leq & 
orm{\Lambda_{a_1,q_1}-\Lambda_{a_2,q_2}} 
orm{f_h}_{H^{1}(\Sigma)}
orm{g_h}_{L^2(\Sigma)}\cr &\leq & Ch^{-3}
orm{	heta_1}_{\mathcal{V}(Q)}
orm{	heta_2}_{\mathcal{V}(Q)}
orm{\Lambda_{a_1,q_1} -\Lambda_{a_2,q_2}}. \end{eqnarray} The estimate (ef{4.2}) follows easily from (ef{4.10}), (ef{4.11}) and (ef{4.12}).\ This completes the proof of the Lemma.

From the equality (ef{4.10}) and the expressions (ef{4.6}) and (ef{4.3}), it follows that  egin{multline} \int_0^T\!\!\!\int_\M q(x)(	heta_2\overline{	heta}_1)(x,t)\psi_{a}(x,t)\,\dv dt = - \int_0^T\!\!\!\int_{\p \M} \overline{g}_h\para{\Lambda_{a_1,q_1}-\Lambda_{a_2,q_2}}f_{h} \ds \, \dd t \cr +ih^{-1}\int_0^T\!\!\!\int_\M a(x) (	heta_2 \overline{	heta}_1)(x,t)(\psi_{a_2}\psi_{-a_1})( x,t)\dv\,\dd t +ih^{-1}\int_0^T\!\!\!\int_\M a(x) (	heta_2\psi_{a_2})(x,t))\overline{r}_{1,h}e^{i\varphi/h}\dv\dd t\cr -\int_0^T\!\!\!\int_\M a(x)\p_t(	heta_2\psi_{a_2})(x,t)(\overline{	heta}_1\psi_{a_1})(x,t)\dv\dd t -\int_0^T\!\!\!\int_\M a(x)\p_t(	heta_2\psi_{a_2})(x,t)\overline{r}_{1,h}(x,t)e^{i\varphi/h}\dv\dd t\cr -\int_0^T\!\!\!\int_\M a(x)\p_t r_{2,h}(\overline{	heta}_1\psi_{a_1})(x,t) e^{-i\varphi/h}\dv\dd t -\int_0^T\!\!\!\int_\M a(x)\p_tr_{2,h}(x,t)\overline{r}_{1,h}(x,t)\dv\dd t\cr -\int_0^T\!\!\!\int_\M q(x)(\overline{	heta}_1\psi_{-a_1})(x,t)r_{2,h}(x,t)e^{-i\varphi/h}\dv\dd t -\int_0^T\!\!\!\int_\M q(x)(	heta_2\psi_{a_2})(x,t)\overline{r}_{1,h}(x,t)e^{i\varphi/h}\dv\dd t\cr -\int_0^T\!\!\!\int_\M q(x)(r_{2,h}\overline{r}_{1,h})(x,t)\dv\dd t . \end{multline} We set $$\int_0^T\!\!\!\int_\M q(x)(	heta_2\overline{	heta}_1)(x,t)\psi_{a}(x,t)\,\dv dt = -\int_0^T\!\!\!\int_{\p \M} \overline{g}_h\para{\Lambda_{a_1,q_1}-\Lambda_{a_2,q_2}}f_{h} \ds \, \dd t +\mathscr{R}'_h.$$ In view of (ef{4.7}) and (ef{4.4}), we have  egin{equation} \abs{\mathscr{R}'_h}\leq C\para{h+h^{-1} \|a\|_{\mathcal{C}^0(\M)}}
orm{	heta_1}_{\mathcal{V}(Q)}
orm{	heta_2}_{\mathcal{V}(Q)}. \end{equation} On the other hand, by the trace theorem, we find  egin{eqnarray}  igg|\int_0^T\!\!\!\int_{\p \M}\para{\Lambda_{a_1,q_1}-\Lambda_{a_2,q_2}}(f_{h}) \overline{g}_h \ds \, \dd t  igg| &\leq & 
orm{\Lambda_{a_1,q_1}-\Lambda_{a_2,q_2}} 
orm{f_h}_{H^{1}(\Sigma)}
orm{g_h}_{L^2(\Sigma)}\cr &\leq & Ch^{-3}
orm{	heta_1}_{\mathcal{V}(Q)}
orm{	heta_2}_{\mathcal{V}(Q)}
orm{\Lambda_{a_1,q_1} -\Lambda_{a_2,q_2}}. \end{eqnarray} Furthermore  egin{multline} \int_0^T\!\!\!\int_\M q(x)(	heta_2\overline{	heta}_1)(x,t)\,\dv dt = \int_0^T\!\!\!\int_\M q(x)(	heta_2\overline{	heta}_1)(x,t)(1-\psi_{a}(x,t))\,\dv dt \cr + \int_0^T\!\!\!\int_\M q(x)(	heta_2\overline{	heta}_1)(x,t)\psi_{a}(x,t)\,\dv dt \end{multline} and since $$ \abs{1-\psi_a(x,t)}\leq C
orm{a}_{\mathcal{C}(\M)} $$ we deduce that $$  igg|\int_0^T\!\!\!\int_\M q(x)(	heta_2\overline{	heta}_1)(x,t)(1-\psi_{a}(x,t))\,\dv dt igg| \leq C
orm{a}_{\mathcal{C}^0(\M)} 
orm{	heta_1}_{\mathcal{V}(Q)}
orm{	heta_2}_{\mathcal{V}(Q)}.$$ Combining with (ef{5.4}), (ef{5.5}) and (ef{5.6}), the estimate (ef{5.2}) follows.\ This completes the proof of the Lemma.

For any $X\in \Gamma({\mathfrak{D}^{T}})$,\,\, $Z\in \Gamma({\mathfrak{D}}^\perp)$ and $V\in \Gamma({\mathfrak{D}}^	heta)$, we have  egin{equation*}  egin{aligned} g(h(X, Z), FV)\;&=g(\widetilde{
abla}_ZX-
abla_ZX, \varphi V-TV)\&=g((\widetilde{
abla}_{Z}\varphi)X, V) -g(\widetilde
